 vocab=[('🧪','chamber','câmara','TCHÊIM-bar'),('🔲','panel','painel','PÂ-nl'),('🔫','turret','torre de tiro','TÂ-rit'),('🧬','prototype','protótipo','PRÔU-to-táip'),('👩‍🔬','subject','participante','SÂB-djékt'),('📊','result','resultado','ri-ZÂLT')],
