 molds=[('Passado',['The chambers','as câmaras'],[(' were tested.',' foram testadas.'),(' were cleaned.',' foram limpas.'),(' were recorded.',' foram registradas.')]),('Em andamento',['The turret is being','a torre está sendo'],[(' repaired.',' consertada.'),(' tested.',' testada.'),(' replaced.',' substituída.')]),('Futuro',['The results will be','os resultados serão'],[(' reviewed.',' revisados.'),(' published.',' publicados.'),(' approved.',' aprovados.')])],
